import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:http/testing.dart';
import 'package:mesting_music/features/music_platform/qishui/qishui_api.dart';
import 'package:mesting_music/features/music_platform/qishui/qishui_request_signer.dart';
import 'qishui_signed_api167_test.dart' show account, reply;
import 'qishui_signer168_test.dart' show config168, signature168, token168;

/// Exports only wholly synthetic requests generated by the real app transport.
/// The independent helper owner can validate these same bytes offline, avoiding
/// a second handwritten contract that accidentally omits the first-page cursor.
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  test(
    'app-generated helper envelopes retain complete exact feature contracts',
    () async {
      final envelopes = <Map<String, dynamic>>[];
      final client = MockClient((request) async {
        if (request.url.host == 'nas.example.test') {
          if (request.url.path == '/config') return config168();
          envelopes.add(
            Map<String, dynamic>.from(jsonDecode(request.body) as Map),
          );
          return signature168();
        }
        return reply({'status_code': 0});
      });
      final api = QishuiApi(
        client,
        signer: SodaMRequestSigner(
          client,
          custom: true,
          endpoint: Uri.parse('https://nas.example.test/sign'),
          accessToken: token168,
        ),
      )..configure(account());
      addTearDown(api.dispose);
      await api.request(
        '/luna/search/track',
        body: const {
          'q': '天外来物',
          'cursor': '0',
          'search_id': 'fixture-177-search',
          'search_method': 'input',
        },
      );
      await api.request(
        '/luna/video/uploader',
        get: true,
        query: const {'track_id': '', 'upload_type': '0', 'scene': '0'},
      );
      await api.request(
        '/luna/me/playlist/update',
        write: true,
        body: const {
          'playlist_id': '17702',
          'cover_uri': 'tos-cn-i-fixture/cover.png',
        },
      );
      await api.request(
        '/luna/user/info',
        get: true,
        query: const {'user_id': '17703'},
      );
      for (final source in ['1', '2']) {
        for (final path in ['following', 'follower']) {
          await api.request(
            '/luna/users/17701/$path',
            get: true,
            query: {'cursor': '', 'count': '20', 'scene': source},
          );
        }
      }
      await api.request(
        '/luna/users/17701/following',
        get: true,
        query: const {'cursor': 'opaque-next', 'count': '20', 'scene': '2'},
      );
      for (final path in ['follow', 'unfollow']) {
        await api.request(
          '/luna/me/$path',
          form: const {'user_id': '17703'},
          write: true,
        );
      }
      await api.request(
        '/luna/me/music_wall',
        body: const {'feed_music_wall_extra': {}, 'ab_param': ''},
      );
      await api.request(
        '/luna/me/collection/artist',
        get: true,
        query: const {'count': '50'},
      );
      await api.request(
        '/luna/me/collection/artist',
        get: true,
        query: const {'count': '50', 'cursor': 'opaque-next'},
      );
      for (final path in [
        '/luna/me/collection/artist',
        '/luna/me/collection/artist/delete',
      ]) {
        await api.request(
          path,
          write: true,
          body: const {
            'artist_ids': ['17720'],
          },
        );
      }
      expect(envelopes, hasLength(16));
      for (final envelope in envelopes) {
        expect(jsonEncode(envelope), isNot(contains('music-secret167')));
        expect(jsonEncode(envelope), isNot(contains(token168)));
      }
      if (const bool.fromEnvironment('EXPORT_177_CONTRACT')) {
        final output = File(
          '.codex-artifacts/2026-11-07-release177/helper-app-envelopes.json',
        );
        output.writeAsStringSync(
          const JsonEncoder.withIndent('  ').convert(envelopes),
        );
      }
    },
  );
}
